function renderPlaces(list, headings) {
  const groups = ["داخل العبور الجديدة", "مدينة العبور القائمة — قريبة من العبور الجديدة"];
  return groups.map((group) => {
    const items = list.filter((p) => p.group === group);
    if (!items.length) return "";
    const cards = items.map((p, index) => `<article class="school-card"><div class="school-card-no">${String(index + 1).padStart(2, "0")}</div><h4>${p.name}</h4><p class="school-area">⌖ ${p.area}</p><p class="school-type">${p.type}</p><div class="school-actions">${p.phone ? `<a href="tel:${p.phone.replace(/\s/g, "")}">${p.phone} ↗</a>` : ""}<a href="${p.source}" target="_blank" rel="noopener noreferrer">المصدر ↗</a><a href="https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(p.maps)}" target="_blank" rel="noopener noreferrer">افتح الخريطة ↗</a></div><small>التحقق: ${p.sourceLabel}</small></article>`).join("");
    return `<section class="school-group"><div class="school-group-head"><span>⌖</span><div><p>${group}</p><h3>${group === "داخل العبور الجديدة" ? headings[0] : headings[1]}</h3></div></div><div class="school-grid">${cards}</div></section>`;
  }).join("");
}

