function landingPage(L) {
  const d = dirBySlug[L.parent];
  const items = d.items.filter((it) => it.c === L.sub);
  const others = landings.filter((x) => x.slug !== L.slug && x.parent === L.parent);
  const cross = (others.length ? others : landings.filter((x) => x.slug !== L.slug)).slice(0, 4);
  return `<main>${pageHero({tag: L.title, eyebrow: "دليل فرعي · أسماء وعناوين وأرقام", title: L.title, description: L.desc})}<section class="paper section"><div class="wrap"><nav class="crumbs"><a href="/directory/">دليل الخدمات</a> ← <a href="/${L.parent}/">${d.title}</a> ← <span>${L.sub}</span></nav><p class="eyebrow">${items.length} مدخلًا · ${items.filter((i) => i.t).length} منها برقم هاتف · مراجعة أغسطس 2026</p><h2>${L.title} — القائمة الكاملة</h2><p class="wide-copy">${L.p1}</p><p class="wide-copy">${L.p2}</p><div class="dir-list">${items.map(dirItem).join("")}</div><p class="caption">المدخل بلا رقم يعني أن الرقم غير متاح في المصدر، لا أن المكان بلا هاتف. العناوين منقولة كما وردت وبعضها مترجم آليًا — عند الالتباس ابحث بالاسم الإنجليزي على خرائط جوجل.</p></div></section><section class="cream section"><div class="wrap content-grid"><article><h2>أدلة قد تحتاجها بعد هذه</h2><p>هذه الصفحة جزء من دليل خدمات أوسع لمدينة العبور والعبور الجديدة، يضم أكثر من 1,300 مدخل موزعة على 16 دليلًا متخصصًا — كلها بالاسم والعنوان والهاتف والمصدر، وبلا ترتيب ولا تقييم ولا إعلانات.</p><div class="related">${cross.map((x) => `<a href="/${x.parent}/${x.slug}/">${x.title} ↖</a>`).join("")}<a href="/${L.parent}/">${d.title} كاملًا ↖</a><a href="/directory/">كل الأدلة ↖</a></div></article><aside class="action-card"><p>الأقرب إليك</p><a class="button" href="/${L.parent}/">${d.title} (${d.items.length}) ↖</a><a class="text-link" href="/emergency/">أرقام الطوارئ ↖</a><a class="text-link" href="/search/">ابحث في كل الأدلة ↖</a></aside></div></section>${refsHtml()}</main>`;
}

function renderSchoolDirectory() {
  const groups = ["داخل العبور الجديدة", "مدينة العبور القائمة — قريبة من العبور الجديدة"];
  return groups.map((group) => {
    const cards = realSchools.filter((school) => school.group === group).map((school, index) => `<article class="school-card"><div class="school-card-no">${String(index + 1).padStart(2, "0")}</div><h4><a href="/schools/${school.slug}/">${school.name}</a></h4><p class="school-area">⌖ ${school.area}</p><p class="school-type">${school.type}</p><div class="school-actions"><a href="/schools/${school.slug}/">التفاصيل ↖</a><a href="${school.source}" target="_blank" rel="noopener noreferrer">المصدر ↗</a><a href="https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(school.maps)}" target="_blank" rel="noopener noreferrer">افتح الخريطة ↗</a></div><small>التحقق: ${school.sourceLabel}</small></article>`).join("");
    const heading = group === "داخل العبور الجديدة" ? "مدارس تقع ضمن نطاق المدينة الجديد" : "خيارات تستلزم قياس رحلة المدرسة اليومية";
    return `<section class="school-group"><div class="school-group-head"><span>⌖</span><div><p>${group}</p><h3>${heading}</h3></div></div><div class="school-grid">${cards}</div></section>`;
  }).join("");
}

const schoolsPage = `<main>${pageHero({tag:"المدارس والتعليم", eyebrow:"دليل فعلي للأسر", title:"مدارس العبور الجديدة: كيف تختار قبل أن تختار الوحدة", description:"أسماء مدارس فعلية داخل العبور الجديدة وحولها، مع المنطقة ونوع التعليم ومصدر يمكن مراجعته قبل الزيارة."})}${atlasBody("خريطة المدارس", "افصل بين المدارس داخل العبور الجديدة والمدارس الموجودة في مدينة العبور القائمة، ثم قِس الرحلة في وقت الطابور.")}<section class="paper section"><div class="wrap"><p class="eyebrow">أين توجد المدارس فعلًا؟</p><h2>دليل مدارس منشور: داخل العبور الجديدة وحولها</h2><p class="wide-copy">هذه ليست قائمة توصيات أو ترتيبًا لأفضل مدرسة. إنها نقاط بداية بأسماء فعلية ومناطق منشورة ومصدر ظاهر. يضم دليل العبور الجديدة المحلي مدارس حكومية ورسمية موزعة على أحياء المجد والحرية والكرامة، بينما توجد مدارس إضافية في مدينة العبور القائمة القريبة. يجب تأكيد المقاعد والرسوم والمراحل المتاحة مباشرةً من المدرسة قبل التقديم.</p><div class="school-directory">${renderSchoolDirectory()}</div></div></section>${schoolsFullList()}<section class="cream section"><div class="wrap content-grid"><article><h2>كيف تستخدم الدليل دون الوقوع في خطأ الموقع؟</h2><p>الاسم وحده لا يكفي. بعض المدارس تقع داخل العبور الجديدة نفسها، وبعضها في مدينة العبور القائمة غرب النطاق. لذلك عند اختيار وحدة، ابدأ بثلاثة أسماء محتملة من القائمة، وافتح الخريطة لكل اسم، ثم قِس الرحلة من باب المشروع إلى بوابة المدرسة في ساعة الذهاب الصباحي وساعة العودة. لا تعتمد على وصف «قريب من المدارس» من دون تحديد المدرسة المقصودة ومسارها الفعلي.</p><p>تظهر القائمة أيضًا أن نوع المدرسة لا يجيب عن كل الأسئلة. قبل التسجيل، تأكد من المرحلة التي تقبلها المدرسة في السنة المطلوبة، ونظام المنهج، والمقاعد المتاحة، والرسوم الكاملة، ورسوم الباص إن كنت ستستخدمه. الصفحات الرسمية قد تتغير مع موسم التقديم، لذلك استخدم الرابط والموقع كأداة تحقق، لا كضمان قبول أو تسعير ثابت.</p><h2>أسئلة تُطرح على أي مدرسة قبل التسجيل</h2><ul class="check-list"><li>✓ ما إجمالي الرسوم السنوية شاملة الأنشطة والزي والكتب والباص؟</li><li>✓ ما سياسة الزيادة السنوية، وهل هي مكتوبة في العقد؟</li><li>✓ كم عدد الطلاب في الفصل الواحد فعليًا هذا العام؟</li><li>✓ ما نسبة استمرار المعلمين من العام الماضي؟</li><li>✓ هل يمكن زيارة المدرسة في يوم دراسي عادي وليس في يوم مفتوح؟</li></ul><p>الزيارة في يوم دراسي عادي تكشف ما لا يظهر في اليوم المفتوح: حركة الطلاب، نظافة المرافق، طريقة تعامل الإدارة، وحالة الفناء والملاعب. إن رفضت المدرسة الزيارة العادية، فهذه إشارة تستحق التوقف. ولأن العبور الجديدة مدينة ممتدة، راقب وقت الباص أيضًا؛ طريق طويل قد يضيف ساعة قبل بداية اليوم الدراسي.</p></article><aside class="action-card"><p>رتّب قرار العائلة</p><a class="button" href="/districts/">قارن الأحياء ↖</a><a class="text-link" href="/transport/">احسب زمن الرحلة ↖</a><a class="text-link" href="/services/">راجع الخدمات الأخرى ↖</a></aside></div></section><section class="section"><div class="wrap"><h2>مصادر الدليل التعليمي</h2><div class="data-table"><div><b>المصدر</b><b>ماذا راجعنا؟</b></div><div><span><a href="https://www.newobour.city/schools-directory.php" target="_blank" rel="noopener noreferrer">دليل مدارس العبور الجديدة ↗</a></span><span>الاسم، الحي، المرحلة، والنوع في نطاق العبور الجديدة.</span></div><div><span><a href="https://nes.moe.gov.eg/" target="_blank" rel="noopener noreferrer">مدارس النيل المصرية الدولية ↗</a></span><span>تأكيد إدراج فرع مدينة العبور في الشبكة الرسمية.</span></div><div><span><a href="https://www.ips-schools.com/" target="_blank" rel="noopener noreferrer">المدارس الرسمية الدولية ↗</a></span><span>تأكيد إدراج فرعي IPS العبور وروضة العبور.</span></div><div><span><a href="https://ejs4students.moe.gov.eg/" target="_blank" rel="noopener noreferrer">بوابة المدارس المصرية اليابانية ↗</a></span><span>الرجوع إلى بوابة القبول الرسمية عند فتح التقديم.</span></div></div><p class="caption">آخر مراجعة للدليل: أغسطس 2026. إذا وجدت بيانات تغيرت، استخدم رابط المصدر للتحقق المباشر قبل اتخاذ قرار السكن أو التسجيل.</p></div></section>${refsHtml()}</main>`;

const healthPage = `<main>${pageHero({tag:"الصحة والمستشفيات", eyebrow:"أهم من السعر", title:"الرعاية الصحية في العبور الجديدة", description:"أقرب مستشفى يعمل 24 ساعة وزمن الوصول إليه ليلًا — معلومة تسبق السعر في ترتيب الأولويات."})}${atlasBody("خريطة الرعاية الصحية", "قِس زمن الوصول لأقرب طوارئ في ساعة متأخرة، لأن هذا هو السيناريو الذي تحتاج فيه المعلومة فعلًا.")}<section class="paper section"><div class="wrap content-grid"><article><h2>السؤال الصحي الأول قبل الشراء</h2><p>قبل أي حديث عن السعر أو التشطيب، اسأل: أين أقرب مستشفى يعمل على مدار 24 ساعة، وكم يستغرق الوصول إليه من باب الوحدة في الثانية صباحًا؟ هذا السيناريو تحديدًا هو الذي تحتاج فيه المعلومة، وهو الذي لا يُسأل عنه غالبًا أثناء المعاينة النهارية المريحة.</p><p>الإجابة تختلف بشكل كبير بين نطاق وآخر داخل المدينة نفسها. بعض المناطق قريبة من مستشفيات العبور القائمة، وبعض نطاقات التوسع تحتاج رحلة أطول. لا تكتفِ بإجابة مكتب المبيعات؛ افتح الخريطة وقِس المسار بنفسك، ثم جرّبه فعليًا إن أمكن.</p><h2>الخدمات الصحية المتاحة</h2><div class="services-list">${health.map(([t,d],i)=>`<article><b>0${i+1}</b><h3>${t}</h3><p>${d}</p></article>`).join("")}</div><h2>أرقام الطوارئ</h2><div class="data-table"><div><b>الجهة</b><b>الرقم</b></div>${emergency.map(([n,t])=>`<div><span>${n}</span><span><strong>${t}</strong></span></div>`).join("")}</div><p class="caption">الأرقام المذكورة هي الخطوط الوطنية المعلنة في مصر. احتفظ بها في هاتفك، وتحقق من أقرب فرع خدمة محلي بعد الانتقال.</p><h2>ما الذي يجب فحصه أثناء المعاينة؟</h2><ul class="check-list"><li>✓ زمن الوصول لأقرب طوارئ ليلًا، وليس نهارًا.</li><li>✓ وجود صيدلية تعمل بعد منتصف الليل في نطاق قريب.</li><li>✓ إمكانية دخول سيارة الإسعاف إلى داخل المشروع ووصولها للمبنى.</li><li>✓ وجود عيادات بتخصصات أساسية (أطفال، باطنة، أسنان) في نطاق معقول.</li><li>✓ تغطية شبكة المحمول داخل الوحدة — تفصيلة تصبح حرجة في الطوارئ.</li></ul><p>نقطة يغفلها كثيرون: تأكد من أن المسار من بوابة المشروع إلى مبناك يسمح بمرور سيارة إسعاف، وأن رقم المبنى واضح من الخارج. في المشروعات الكبيرة قد يضيع وقت ثمين في البحث عن العنوان الصحيح.</p><h2>التأمين الصحي وشبكة المستشفيات</h2><p>إذا كان لديك تأمين صحي من العمل أو تأمين خاص، تحقق من شبكة المستشفيات المتعاقدة وأيها يقع في نطاق معقول من موقعك الجديد. الانتقال إلى منطقة بعيدة عن مستشفيات شبكتك يعني إما رحلات أطول أو دفعًا نقديًا في الحالات العادية. هذه تكلفة حقيقية تُحسب ضمن قرار الموقع.</p><p>اسأل أيضًا عن أقرب مركز أشعة ومعمل تحاليل متعاقد، لأن هذه الخدمات تُستخدم بتكرار أكبر من المستشفى نفسه. وإذا كان في العائلة مريض مزمن يحتاج متابعة دورية، فاجعل قرب طبيبه المعالج أحد معايير اختيار الموقع من البداية.</p><h2>الاحتياجات الصحية الخاصة</h2><p>لكبار السن وذوي الاحتياجات الخاصة اعتبارات إضافية: هل المبنى مزود بمصعد يتسع لكرسي متحرك؟ هل المداخل بها منحدرات؟ هل الطرق الداخلية للمشروع ممهدة وآمنة للمشي؟ هذه أسئلة تُطرح قبل الشراء لأن تعديلها لاحقًا مكلف أو مستحيل.</p><p>وللعائلات التي تنتظر مولودًا أو لديها أطفال صغار، اسأل عن أقرب طبيب أطفال وأقرب مستشفى به قسم حضانات، وعن زمن الوصول ليلًا. حمى مفاجئة في الثالثة صباحًا هي الاختبار الحقيقي لقرار الموقع، وليس جولة نهارية مريحة.</p><h2>الصيدليات ومواعيد العمل الفعلية</h2><p>الصيدلية أكثر خدمة صحية استخدامًا، ومع ذلك يغفلها معظم المشترين. تحقق من وجود صيدلية على بُعد دقائق، ومن مواعيد عملها الفعلية لا المعلنة. اسأل جارًا مقيمًا إن أمكن: هل تجد صيدلية مفتوحة بعد منتصف الليل؟ الإجابة تختلف كثيرًا بين نطاق وآخر داخل المدينة نفسها.</p></article><aside class="fact-rail"><span class="tag">⌖ قاعدة عملية</span><div><b>القاعدة</b><span>قِس المسافة الصحية في أسوأ سيناريو، لا في أفضل واحد.</span></div><div><b>الاختبار</b><span>جرّب الطريق لأقرب مستشفى مرة واحدة قبل الشراء.</span></div><div><b>التوثيق</b><span>احفظ العنوان الدقيق وأقرب مدخل في هاتفك بعد الانتقال.</span></div></aside></div></section>${refsHtml()}</main>`;


const pharmaciesPage = `<main>${pageHero({tag:"الصيدليات", eyebrow:"خدمة يومية لا تحتمل التأجيل", title:"صيدليات العبور: أين تجدها فعلًا حول العبور الجديدة", description:"أسماء صيدليات فعلية بالمنطقة والتليفون ومصدر منشور، مع تنبيه صريح إلى أن معظمها يقع في مدينة العبور القائمة لا داخل المدينة الجديدة."})}${atlasBody("خريطة الصيدليات", "الصيدلية القريبة نهارًا ليست بالضرورة مفتوحة الثانية صباحًا؛ اسأل عن المناوبة قبل أن تحسبها ميزة موقع.")}<section class="paper section"><div class="wrap"><p class="eyebrow">قبل القائمة: حقيقة يجب أن تُقال</p><h2>داخل العبور الجديدة لا توجد حتى الآن صيدليات منشورة</h2><p class="wide-copy">راجعنا دليل الخدمات الرسمي لمدينة العبور الجديدة فوجدنا قسم الصيدليات فارغًا تمامًا حتى تاريخ هذه المراجعة. هذا لا يعني عدم وجود صيدلية واحدة على الأرض، لكنه يعني أن أي عرض عقاري يَعِدك بـ«خدمات متكاملة» داخل المدينة الجديدة يجب أن تسأله سؤالًا واحدًا مباشرًا: أين الصيدلية بالضبط، وما اسمها؟ الصيدليات التي يستخدمها سكان العبور الجديدة اليوم موجودة في مدينة العبور القائمة وجولف سيتي وحي الشباب، وهي مسافة سيارة لا مسافة مشي.</p><p class="wide-copy">هذه المعلومة تغيّر شكل القرار. إذا كان في العائلة طفل صغير أو مريض مزمن أو كبير سن، فإن زمن الوصول إلى أقرب صيدلية مفتوحة ليلًا يسبق في الأهمية فرق بضعة آلاف في سعر المتر. القائمة أدناه نقطة بداية بأسماء ومناطق ومصادر ظاهرة، وليست ترتيبًا ولا توصية.</p><div class="school-directory">${renderPlaces(pharmacies, ["صيدليات داخل نطاق المدينة الجديدة", "الصيدليات التي يستخدمها سكان العبور الجديدة فعليًا"])}</div></div></section><section class="cream section"><div class="wrap content-grid"><article><h2>كيف تقيس تغطية الصيدليات قبل الشراء؟</h2><p>افتح الخريطة من موقع الوحدة نفسها لا من حدود المدينة، واختر أقرب ثلاث صيدليات من القائمة. قِس زمن السيارة إلى كل واحدة في وقت متأخر من الليل، لأن هذا هو التوقيت الذي تحتاج فيه المعلومة فعلًا. ثم اتصل بالصيدلية واسأل سؤالًا واحدًا: هل تفتحون 24 ساعة أم حتى أي ساعة؟ الإجابة على التليفون أدق من أي لافتة أو إعلان.</p><p>انتبه أيضًا إلى الفرق بين السلسلة والصيدلية المستقلة. السلاسل الكبرى مثل سيف والعزبي تتيح عادةً توفر أوسع للأصناف وخدمة توصيل ومواعيد أطول، بينما الصيدلية المحلية قد تكون أقرب إليك بكثير. الأفضل عمليًا أن تعرف واحدة من كل نوع: قريبة للطوارئ الصغيرة، وسلسلة للأدوية التي لا تتوفر في كل مكان.</p><h2>أسئلة تُطرح قبل أن تحسب الصيدلية ميزة موقع</h2><ul class="check-list"><li>✓ ما مواعيد العمل الفعلية، وهل هناك مناوبة بعد منتصف الليل؟</li><li>✓ هل يوجد توصيل، وما نطاقه وحدّه الأدنى؟</li><li>✓ هل تتوفر الأدوية المزمنة بانتظام أم بالطلب المسبق؟</li><li>✓ ما أقرب صيدلية بديلة إذا كانت مغلقة؟</li><li>✓ كم يستغرق الطريق إليها ليلًا من باب المشروع لا من حدود المدينة؟</li></ul><p>لو كانت إجابة أي من هذه الأسئلة غير مريحة، فهذه ليست نهاية العالم — لكنها تكلفة يومية حقيقية يجب أن تدخل في المقارنة بين مشروع وآخر، تمامًا مثل زمن رحلة المدرسة وزمن الوصول إلى أقرب طوارئ.</p></article><aside class="action-card"><p>أكمل فحص الخدمات</p><a class="button" href="/health/">الصحة والمستشفيات ↖</a><a class="text-link" href="/restaurants/">دليل المطاعم ↖</a><a class="text-link" href="/services/">كل الخدمات ↖</a><a class="text-link" href="/districts/">قارن الأحياء ↖</a></aside></div></section><section class="section"><div class="wrap"><h2>مصادر دليل الصيدليات</h2><div class="data-table"><div><b>المصدر</b><b>ماذا راجعنا؟</b></div><div><span><a href="https://yellowpages.com.eg/ar/category/%D9%85%D8%AF%D9%8A%D9%86%D8%A9-%D8%A7%D9%84%D8%B9%D8%A8%D9%88%D8%B1-%D8%B5%D9%8A%D8%AF%D9%84%D9%8A%D8%A7%D8%AA/3262" target="_blank" rel="noopener noreferrer">Yellow Pages Egypt — صيدليات مدينة العبور ↗</a></span><span>الاسم والعنوان والتليفون كما هو منشور في الدليل.</span></div><div><span><a href="https://www.newobour.city/services.php?cat_id=1" target="_blank" rel="noopener noreferrer">دليل خدمات العبور الجديدة ↗</a></span><span>قسم الصيدليات — لا توجد خدمات منشورة فيه حتى تاريخ المراجعة.</span></div><div><span><a href="https://www.elezabypharmacy.com/ar/store-locator/" target="_blank" rel="noopener noreferrer">محدد فروع صيدليات العزبي ↗</a></span><span>تأكيد وجود فرع في نطاق العبور.</span></div></div><p class="caption">آخر مراجعة: أغسطس 2026. لا يعرض الدليل مواعيد عمل أو خدمة 24 ساعة لأي صيدلية لأن هذه البيانات غير منشورة في مصدر موثوق — تحقق منها بمكالمة قبل أن تبني عليها قرارًا. إذا وجدت بيانات تغيّرت، ارجع لرابط المصدر.</p></div></section>${refsHtml()}</main>`;

const restaurantsPage = `<main>${pageHero({tag:"المطاعم والكافيهات", eyebrow:"الحياة اليومية بعد الانتقال", title:"مطاعم العبور: القائمة الفعلية حول العبور الجديدة", description:"أسماء مطاعم وكافيهات فعلية بالمنطقة والتصنيف ومصدر منشور، مقسّمة بين ما هو داخل العبور الجديدة وما هو في المدينة القائمة القريبة."})}${atlasBody("خريطة المطاعم", "قِس المسافة من باب المشروع لا من حدود المدينة، وافصل بين ما يفتح طول الأسبوع وما يعمل في المواسم فقط.")}<section class="paper section"><div class="wrap"><p class="eyebrow">قبل القائمة: أين المطاعم فعلًا؟</p><h2>مطعمان فقط منشوران داخل العبور الجديدة — والباقي في المدينة القائمة</h2><p class="wide-copy">دليل الخدمات الرسمي لمدينة العبور الجديدة يعرض حتى الآن مطعمين اثنين فقط، وكلاهما مشروع أكل بيتي منزلي. أما المطاعم والسلاسل التي يعرفها الناس — من ماكدونالدز وKFC إلى الكبابجي والحواوشي والأسماك — فهي كلها في مدينة العبور القائمة وجولف سيتي وحي الشباب والمنطقة الصناعية. هذه ليست ملاحظة سلبية عن المدينة الجديدة بقدر ما هي وصف دقيق لمرحلتها الحالية: مدينة تُبنى، وخدماتها اليومية ما زالت تُستعار من جارتها.</p><p class="wide-copy">ماذا يعني ذلك عمليًا؟ يعني أن «قريب من كل الخدمات» في إعلان عقاري داخل العبور الجديدة يجب أن يُترجم إلى رقم: كم دقيقة بالسيارة إلى جولف سيتي أو محور العبور؟ القائمة أدناه تعطيك أسماء حقيقية تقيس عليها بدل أن تقيس على وعد.</p><div class="school-directory">${renderPlaces(restaurants, ["مطاعم منشورة داخل حدود المدينة الجديدة", "المطاعم والسلاسل التي يقصدها سكان العبور الجديدة"])}</div></div></section><section class="cream section"><div class="wrap content-grid"><article><h2>كيف تقرأ هذه القائمة قبل اختيار الوحدة؟</h2><p>لاحظ تجمع الأسماء في ثلاث نقاط: جولف سيتي على طريق مصر إسماعيلية الصحراوي، ومحور العبور، وحي الشباب. هذه هي مراكز الخدمة الفعلية في المنطقة. عند مقارنة مشروعين، احسب زمن الوصول من كل واحد إلى أقرب نقطة من الثلاث، وستجد أن الفرق بينهما أوضح بكثير من الفرق في وصف الكتالوج.</p><p>لا يعرض هذا الدليل تقييمًا ولا ترتيبًا ولا أسعارًا. السبب بسيط: تقييمات المطاعم تتغير بسرعة، والأسعار تتغير أسرع، ونشرها بلا مصدر مؤرخ يحوّل الدليل من مرجع إلى إعلان. ما نعرضه هو الاسم والمنطقة والتصنيف والمصدر — والباقي تتحقق منه بنفسك في الزيارة الأولى.</p><h2>ثلاث ملاحظات عملية لسكان المدينة الجديدة</h2><ul class="check-list"><li>✓ خدمات التوصيل تصل إلى العبور الجديدة بشكل متفاوت — اسأل قبل الاعتماد عليها يوميًا</li><li>✓ الأسماء المتجمعة على الطريق الصحراوي أسهل وصولًا بالسيارة وأصعب مشيًا</li><li>✓ مشروعات الأكل البيتي داخل المدينة خيار حقيقي للأسر، لكنها تعمل بالطلب لا بالمحل</li></ul><p>إذا كنت تنتقل إلى المدينة الجديدة قبل اكتمال خدماتها، فالأفضل أن تدخل وأنت تعرف هذه الخريطة، لا أن تكتشفها بعد الاستلام. أغلب الندم بعد الانتقال سببه فجوة بين ما تخيّله المشتري عن الحياة اليومية وما وجده فعلًا.</p></article><aside class="action-card"><p>أكمل فحص الخدمات</p><a class="button" href="/services/">كل الخدمات ↖</a><a class="text-link" href="/pharmacies/">دليل الصيدليات ↖</a><a class="text-link" href="/schools/">دليل المدارس ↖</a><a class="text-link" href="/transport/">احسب زمن الرحلة ↖</a></aside></div></section><section class="section"><div class="wrap"><h2>مصادر دليل المطاعم</h2><div class="data-table"><div><b>المصدر</b><b>ماذا راجعنا؟</b></div><div><span><a href="https://yellowpages.com.eg/ar/category/%D9%85%D8%AF%D9%8A%D9%86%D8%A9-%D8%A7%D9%84%D8%B9%D8%A8%D9%88%D8%B1-%D9%85%D8%B7%D8%A7%D8%B9%D9%85/3262" target="_blank" rel="noopener noreferrer">Yellow Pages Egypt — مطاعم مدينة العبور ↗</a></span><span>الأسماء والعناوين في تصنيف المطاعم العام.</span></div><div><span><a href="https://yellowpages.com.eg/ar/category/%D9%85%D8%AF%D9%8A%D9%86%D8%A9-%D8%A7%D9%84%D8%B9%D8%A8%D9%88%D8%B1-%D9%88%D8%AC%D8%A8%D8%A7%D8%AA-%D8%B3%D8%B1%D9%8A%D8%B9%D8%A9/3262" target="_blank" rel="noopener noreferrer">Yellow Pages Egypt — وجبات سريعة ↗</a></span><span>السلاسل والوجبات السريعة ومواقعها.</span></div><div><span><a href="https://yellowpages.com.eg/ar/category/%D9%85%D8%AF%D9%8A%D9%86%D8%A9-%D8%A7%D9%84%D8%B9%D8%A8%D9%88%D8%B1-%D9%85%D8%B4%D9%88%D9%8A%D8%A7%D8%AA/3262" target="_blank" rel="noopener noreferrer">Yellow Pages Egypt — مشويات ↗</a></span><span>الكبابجي والحواوشي والمشويات.</span></div><div><span><a href="https://www.newobour.city/services.php?cat_id=5" target="_blank" rel="noopener noreferrer">دليل خدمات العبور الجديدة ↗</a></span><span>قسم المطاعم داخل المدينة الجديدة — مدخلان فقط.</span></div></div><p class="caption">آخر مراجعة: أغسطس 2026. الدليل لا ينشر تقييمات ولا أسعارًا ولا مواعيد عمل لأنها غير موثقة في مصدر ثابت. إذا تغيّر عنوان أو أُغلق مكان، استخدم رابط المصدر للتحقق أو أرسل تصحيحًا موثقًا.</p></div></section>${refsHtml()}</main>`;

const emergencyPage = `<main>${pageHero({tag:"الطوارئ", eyebrow:"صفحة تُفتح وقت الحاجة لا وقت القراءة", title:"أرقام وخدمات الطوارئ في العبور", description:"أرقام الطوارئ الرسمية بأزرار اتصال مباشرة، وأقرب الصيدليات، وما يجب أن تعرفه قبل أن تحتاجه."})}<section class="paper section"><div class="wrap"><p class="eyebrow">اضغط الرقم للاتصال مباشرة</p><h2>الأرقام الرسمية</h2><div class="emergency-grid">${emergency.map(([name, num]) => `<a class="emergency-card" href="tel:${num}"><b>${num}</b><span>${name}</span></a>`).join("")}</div><p class="caption">هذه أرقام الخدمات الرسمية وتعمل من أي خط. احفظ الرقم الموحد <strong>16528</strong> في هاتفك الآن — لا وقت للبحث عنه لاحقًا.</p></div></section><section class="cream section"><div class="wrap content-grid"><article><h2>قبل أن تحتاجها: ثلاث معلومات اعرفها اليوم</h2><p>الطوارئ لا تُدار وقت وقوعها بل قبلها. المعلومة التي تحتاجها في الثالثة صباحًا لن تكون متاحة للبحث في تلك اللحظة، لذلك اجمعها الآن وسجّلها في هاتفك وفي ورقة على الثلاجة.</p><ul class="check-list"><li>✓ اسم أقرب مستشفى يعمل 24 ساعة، وزمن الوصول إليه <strong>ليلًا</strong> من باب مسكنك</li><li>✓ اسم ورقم صيدلية تفتح بعد منتصف الليل في نطاقك</li><li>✓ رقم فني الأعطال المعتمد لدى اتحاد الشاغلين أو إدارة المشروع (كهرباء · مصاعد · سباكة)</li></ul><p>المعلومة الثالثة تحديدًا هي التي يهملها معظم السكان الجدد. في المدن الجديدة قد لا تجد فنيًا متاحًا بعد منتصف الليل إلا عبر إدارة المشروع نفسها، لذلك اسأل عنها من اليوم الأول للاستلام لا وقت العطل.</p><h2>لماذا الصيدلية الليلية مسألة موقع لا مسألة راحة؟</h2><p>راجعنا دليل الخدمات الرسمي لمدينة العبور الجديدة فوجدنا قسم الصيدليات فيه فارغًا تمامًا حتى تاريخ هذه المراجعة. الصيدليات التي يستخدمها ساكن المدينة الجديدة اليوم كلها في مدينة العبور القائمة وجولف سيتي وحي الشباب — أي مسافة سيارة لا مسافة مشي. هذه ليست تفصيلة، بل عامل يدخل في المقارنة بين مشروع وآخر تمامًا مثل السعر.</p><p>افتح دليل الصيدليات، اختر أقرب ثلاث، واتصل بها بسؤال واحد: حتى أي ساعة تفتحون؟ الإجابة على الهاتف أدق من أي لافتة.</p></article><aside class="action-card"><p>الأقرب إليك الآن</p><a class="button" href="/pharmacies/">دليل الصيدليات ↖</a><a class="text-link" href="/health/">الصحة والمستشفيات ↖</a><a class="text-link" href="/services/">كل الخدمات ↖</a><a class="text-link" href="/transport/">زمن الوصول ↖</a></aside></div></section><section class="section"><div class="wrap narrow"><h2>ما الذي لا تعرضه هذه الصفحة؟</h2><p>لا تعرض أسماء مستشفيات أو أرقام فنيين أو مناوبات صيدليات، لأن أيًا من ذلك غير منشور في مصدر ثابت ومؤرخ يمكن الرجوع إليه. نشر رقم خاطئ في صفحة طوارئ أسوأ من عدم نشره. إن كانت لديك معلومة موثقة عن مستشفى يعمل 24 ساعة في نطاق العبور أو صيدلية مناوبة، فالدليل يرحّب بإضافتها مع مصدرها.</p><p class="caption">آخر مراجعة: أغسطس 2026.</p></div></section>${refsHtml()}</main>`;

const searchScript = String.raw`
(function(){
  var norm=function(t){return String(t||"").toLowerCase()
    .replace(/[ً-ْـ]/g,"")
    .replace(/[أإآٱ]/g,"ا")
    .replace(/ى/g,"ي").replace(/ة/g,"ه")
    .replace(/[^\p{L}\p{N}]+/gu," ").trim();};
  var input=document.getElementById("q"),
      status=document.getElementById("search-status"),
      out=document.getElementById("search-results"),
      idx=null,timer=null;
  var q=new URLSearchParams(location.search).get("q")||"";
  if(input&&q)input.value=q;
  function card(it,i){
    var a=document.createElement("article");a.className="school-card";
    var no=document.createElement("div");no.className="school-card-no";no.textContent=("0"+(i+1)).slice(-2);
    var h=document.createElement("h4");var link=document.createElement("a");
    link.href=it.u;link.textContent=it.n;h.appendChild(link);
    a.appendChild(no);a.appendChild(h);
    if(it.a){var ar=document.createElement("p");ar.className="school-area";ar.textContent="⌘ "+it.a;a.appendChild(ar);}
    if(it.t){var ty=document.createElement("p");ty.className="school-type";ty.textContent=it.t;a.appendChild(ty);}
    var sm=document.createElement("small");sm.textContent=it.k;a.appendChild(sm);
    return a;
  }
  function run(query){
    if(!out||!status)return;
    var nq=norm(query);out.textContent="";
    if(!nq){status.textContent="اكتب كلمة وابدأ البحث.";return;}
    if(!idx){status.textContent="جارٍ التحميل…";return;}
    var words=nq.split(" ").filter(Boolean),hits=[];
    for(var i=0;i<idx.length;i++){
      var it=idx[i];
      if(!it._s)it._s=norm(it.n+" "+(it.a||"")+" "+(it.t||"")+" "+(it.d||"")+" "+(it.k||""));
      var sc=0,ok=true;
      for(var w=0;w<words.length;w++){
        var pos=it._s.indexOf(words[w]);
        if(pos<0){ok=false;break;}
        sc+=pos===0?3:1;
      }
      if(ok){if(norm(it.n).indexOf(words[0])===0)sc+=4;if(it.k==="صفحة")sc+=2;hits.push([sc,it]);}
    }
    hits.sort(function(a,b){return b[0]-a[0];});
    if(!hits.length){status.textContent="لا توجد نتيجة.";return;}
    status.textContent=hits.length+" نتيجة";
    var f=document.createDocumentFragment();
    for(var j=0;j<hits.length&&j<60;j++)f.appendChild(card(hits[j][1],j));
    out.appendChild(f);
  }
  fetch("/search-index.json").then(function(r){return r.json();}).then(function(d){idx=d;run(input?input.value:q);}).catch(function(){if(status)status.textContent="تعذر تحميل الفهرس.";});
  if(input)input.addEventListener("input",function(){clearTimeout(timer);timer=setTimeout(function(){run(input.value);},150);});
})();
`;

const searchPage = `<main>${pageHero({tag:"البحث", eyebrow:"كل صفحات الدليل ومداخله", title:"ابحث في دليل العبور", description:"ابحث في الصفحات وفي أدلة المدارس والصيدليات والمطاعم — بالاسم أو المنطقة أو نوع الخدمة."})}<section class="paper section"><div class="wrap"><form class="search-page-form" role="search" action="/search/" method="get"><input type="search" id="q" name="q" placeholder="مثال: صيدلية · مدرسة · مشويات · الحي الأول" aria-label="كلمة البحث" autofocus><button type="submit">ابحث</button></form><p class="caption" id="search-status">اكتب كلمة وابدأ البحث.</p><div id="search-results" class="school-grid"></div><noscript><p class="note">البحث يحتاج تفعيل JavaScript. تصفّح مباشرة: <a href="/schools/">المدارس</a> · <a href="/pharmacies/">الصيدليات</a> · <a href="/restaurants/">المطاعم</a> · <a href="/districts/">الأحياء</a>.</p></noscript></div></section><script>${searchScript}</script></main>`;

const investPage = `<main>${pageHero({tag:"الاستثمار العقاري", eyebrow:"أربع حالات مختلفة", title:"الاستثمار في العبور الجديدة: أي حالة أنت؟", description:"لا توجد نصيحة واحدة تناسب الجميع. السكن العائلي يختلف عن الشراء المبكر، والإيجاري يختلف عن إعادة البيع — ولكل حالة معيار مخاطرة مختلف."})}${atlasBody("خريطة حالات الشراء", "حدد حالتك أولًا؛ المعيار الذي يهمك يتغير كليًا بتغير الهدف من الشراء.")}<section class="paper section"><div class="wrap content-grid"><article><h2>ابدأ بتحديد حالتك</h2><p>أكثر الأخطاء شيوعًا في القرار العقاري أن ينصح شخص شخصًا آخر بناءً على تجربته هو، رغم اختلاف الهدف كليًا. من اشترى للسكن يقيس النجاح بجودة الحياة اليومية، ومن اشترى مبكرًا يقيسه بفارق السعر بعد التسليم، ومن اشترى للإيجار يقيسه بصافي العائد. لذلك لا تسأل «هل العبور الجديدة استثمار جيد؟» بل «هل تناسب حالتي أنا؟».</p><div class="services-list">${investCases.map(([t,d],i)=>`<article><b>0${i+1}</b><h3>${t}</h3><p>${d}</p></article>`).join("")}</div><h2>كيف تحسب العائد دون تفاؤل زائد؟</h2><p>ابدأ من التكلفة الكلية لا سعر الوحدة: السعر، وديعة الصيانة، رسوم الإدارة السنوية، التشطيب، ومصاريف التعاقد. ثم احسب الدخل المتوقع بعد خصم فترات الخلو (شهر أو شهران سنويًا في المتوسط)، والصيانة الدورية، وأي عمولة تأجير. الرقم الناتج هو العائد الواقعي، وغالبًا يقل بوضوح عن الرقم المتداول في الإعلانات.</p><p>إذا كان الشراء بالتقسيط، أضف تكلفة التمويل: الفرق بين السعر النقدي وإجمالي الأقساط. هذا الفرق قد يستهلك عائد سنوات إن لم يكن محسوبًا. ولا تبنِ الحساب على نمو سعري مستقبلي؛ نسب الارتفاع السابقة بيان تاريخي وليست وعدًا.</p><h2>ما الذي يرفع المخاطرة فعليًا؟</h2><p>ثلاثة عوامل: عدم وضوح الجهة المنفذة، وعدم اكتمال المرافق في النطاق، وغياب موعد تسليم مكتوب. أي واحد منها بمفرده قد يكون مقبولًا مقابل خصم كافٍ. اجتماع اثنين أو ثلاثة معًا يحتاج توقفًا وإعادة تقييم، لأن كل عامل يضاعف أثر الآخر. قبل الالتزام، راجع <a href="/developers/">مقارنة المطورين على المعايير المنشورة</a> لتفهم ما هو متاح من بيانات موثقة لكل شركة.</p><p>في المقابل، تنخفض المخاطرة مع سابقة أعمال قابلة للزيارة، وإدارة معلنة بعد التسليم، ومستندات أرض وترخيص واضحة، وعقد مفصل. هذه العناصر لا تضمن ربحًا، لكنها تقلل احتمالات الخسارة غير المتوقعة — وهذا هو جوهر إدارة المخاطرة في العقار.</p><h2>متى يكون الانتظار أفضل من الشراء؟</h2><p>عندما لا تستطيع الإجابة على ثلاثة أسئلة: أين تقع الوحدة بالضبط؟ ما مرحلة المرافق حولها؟ ومن ينفذ ويدير؟ غياب أي من هذه الإجابات يعني أن السعر المنخفض قد يكون تعويضًا عن مخاطرة لم تُحسب بعد. الانتظار حتى تتضح الإجابات ليس تردّدًا؛ هو جزء من التقييم.</p><h2>كيف تحسب العائد الإيجاري بشكل واقعي؟</h2><p>العائد الإيجاري الحقيقي ليس الإيجار السنوي مقسومًا على سعر الوحدة. احسبه كالتالي: الإيجار السنوي، ناقص رسوم الصيانة والإدارة، ناقص متوسط فترة الخلو بين مستأجرين (شهر إلى شهرين سنويًا في المناطق الجديدة)، ناقص تكلفة التجديد الدوري، ناقص الضرائب المستحقة. الناتج مقسومًا على إجمالي ما دفعته شاملًا التشطيب والأثاث.</p><p>الفارق بين الحساب البسيط والحساب الواقعي كبير غالبًا. وحدة تبدو بعائد ثمانية بالمئة قد تنتهي عند خمسة أو أقل بعد خصم البنود أعلاه. هذا لا يعني أن الاستثمار سيئ، لكنه يعني أن المقارنة مع بدائل أخرى يجب أن تتم على أساس الرقم الواقعي لا المعلن.</p><h2>الطلب الإيجاري: من سيسكن وحدتك؟</h2><p>قبل الشراء بغرض التأجير، حدد المستأجر المتوقع. هل هي عائلة تعمل في المنطقة الصناعية؟ طالب في جامعة قريبة؟ موظف يعمل في شرق القاهرة ويبحث عن سكن أرخص؟ لكل شريحة متطلبات مختلفة في المساحة والتشطيب والموقع، والشراء بدون تحديدها يعني وحدة قد لا تناسب أحدًا تحديدًا.</p><p>تحقق من الطلب فعليًا: ابحث عن إعلانات إيجار في نفس المنطقة، وسجّل عددها ومدة بقائها منشورة والأسعار المطلوبة. إعلانات كثيرة باقية شهورًا تعني عرضًا أكبر من الطلب. إعلانات قليلة تختفي بسرعة تعني طلبًا جيدًا. هذا بحث مجاني يستغرق ساعة ويغيّر قرارك أحيانًا.</p><h2>الاستثمار طويل الأجل مقابل المضاربة</h2><p>المضاربة تعني الشراء بغرض البيع خلال سنة أو سنتين للاستفادة من فارق السعر بين المراحل. هي أعلى مخاطرة وتعتمد على استمرار ارتفاع السوق وعلى قدرتك على البيع في وقت محدد. الاستثمار طويل الأجل يعتمد على العائد الإيجاري ونمو القيمة عبر سنوات، وهو أقل حساسية لتقلبات قصيرة.</p><p>حدد أي النوعين تمارس قبل الشراء، لأن كل واحد يفرض اختيارًا مختلفًا. المضارب يحتاج مشروعًا في مرحلة مبكرة بسعر أقل من السوق وبمعروض محدود. المستثمر طويل الأجل يحتاج موقعًا بطلب إيجاري مستقر وإدارة جيدة تحافظ على حالة المشروع. الخلط بينهما هو سبب شائع لخيبة التوقعات.</p></article><aside class="action-card"><p>قارن قبل أن تحسب</p><a class="button" href="/prices/">افتح قراءة الأسعار ↖</a><a class="text-link" href="/developers/">قيّم الجهة المنفذة ↖</a><a class="text-link" href="/compare/">قارن بمدن أخرى ↖</a></aside></div></section>${refsHtml()}</main>`;

const mistakesPage = `<main>${pageHero({tag:"أخطاء شائعة", eyebrow:"تعلّم من غيرك", title:"ستة أخطاء تتكرر عند الشراء في المدن الجديدة", description:"معظم الندم بعد الشراء يعود إلى أخطاء يمكن تجنبها بسؤال واحد في الوقت المناسب. هذه أكثرها تكرارًا."})}${atlasBody("قائمة الأخطاء المتكررة", "كل خطأ أدناه له سؤال مضاد يمنعه؛ اطرح السؤال قبل الدفع لا بعده.")}<section class="paper section"><div class="wrap narrow"><div class="faq-list">${mistakes.map(([t,d],i)=>`<details${i===0?" open":""}><summary>${i+1}. ${t}<span>⌄</span></summary><p>${d}</p></details>`).join("")}</div></div></section><section class="section"><div class="wrap content-grid"><article><h2>لماذا تتكرر هذه الأخطاء تحديدًا؟</h2><p>القرار العقاري يجمع بين مبلغ كبير وضغط زمني وعاطفة. هذا المزيج يدفع المشتري إلى الاختصار: يثق في انطباع بدل مستند، ويقارن سعرين غير متكافئين، ويؤجل قراءة العقد إلى ما بعد الدفع. الأخطاء أعلاه ليست نتيجة قلة ذكاء، بل نتيجة ترتيب خاطئ للخطوات.</p><p>العلاج بسيط: اجعل كل خطوة مكتوبة. ورقة واحدة لكل مشروع تحتوي زمن الوصول، حالة الخدمات، التكلفة الكلية، موعد التسليم، واسم جهة الإدارة. عندما ترى ثلاثة مشروعات جنبًا إلى جنب على الورق، تختفي معظم الأخطاء تلقائيًا لأن الفراغات تصبح مرئية.</p><h2>السؤال المضاد لكل خطأ</h2><ul class="check-list"><li>✓ بدل «الإعلان جميل» → «متى يمكنني زيارة الموقع في يوم عمل؟»</li><li>✓ بدل «التقسيط مريح» → «ما السعر النقدي وما إجمالي الأقساط؟»</li><li>✓ بدل «الرسوم بسيطة» → «ما قيمة الوديعة والرسوم السنوية مكتوبة؟»</li><li>✓ بدل «وعدوني بكذا» → «هل يمكن إضافة هذا البند إلى العقد؟»</li><li>✓ بدل «العرض ينتهي اليوم» → «أحتاج مهلة لقراءة العقد.»</li><li>✓ بدل «المسافة قريبة» → «كم استغرقت الرحلة فعليًا في الذروة؟»</li></ul><p>الأسئلة الستة أعلاه لا تحتاج خبرة عقارية. تحتاج فقط أن تُطرح قبل الدفع لا بعده. والمشروع الجاد يرحب بها، لأن وضوح الإجابة يخدمه هو أيضًا في تقليل الخلافات لاحقًا.</p><h2>خطأ سابع: الاعتماد على رأي شخص واحد</h2><p>كثير من قرارات الشراء تُبنى على رأي قريب أو صديق اشترى في نفس المشروع وكان راضيًا. تجربته حقيقية لكنها ليست كافية: قد يكون اشترى في مرحلة مختلفة، بسعر مختلف، في موقع مختلف داخل المشروع نفسه. الرضا في وحدة لا يعني الرضا في كل الوحدات.</p><p>اسأل ثلاثة أشخاص على الأقل، ويفضل أن يكون أحدهم غير راضٍ. المشتري غير الراضي يخبرك بما لا يظهر في الجولة التسويقية: تأخير التسليم، مشاكل الصيانة، رسوم غير متوقعة، صعوبة التواصل مع الإدارة. هذه المعلومات أثمن من عشر مراجعات إيجابية.</p><h2>خطأ ثامن: تجاهل ما بعد الاستلام</h2><p>ينتهي تفكير كثير من المشترين عند لحظة الاستلام، بينما تبدأ التكلفة الحقيقية بعدها: رسوم الصيانة السنوية، فواتير المرافق، تكلفة التشطيب، الأثاث، ثم الانتقال نفسه. اجمع هذه الأرقام قبل التوقيع وأضفها إلى سعر الوحدة، لأنها تمثل نسبة معتبرة من التكلفة الكلية.</p><p>واسأل تحديدًا: من يتحمل تكلفة توصيل المرافق؟ هل عداد الكهرباء والمياه ضمن السعر أم يُدفع منفصلًا؟ ما رسوم استلام الوحدة إن وُجدت؟ هذه بنود صغيرة منفردة لكنها تتراكم إلى مبلغ مفاجئ إن لم تكن محسوبة.</p><h2>كيف تحوّل هذه الأخطاء إلى قائمة فحص؟</h2><p>خذ الأخطاء الثمانية واكتب مقابل كل واحد إجابة مشروعك المرشح. إذا عجزت عن ملء خانتين أو أكثر، فأنت لا تملك معلومات كافية للقرار بعد — وهذا في حد ذاته نتيجة مفيدة. القرار المؤجل أسبوعين حتى تكتمل الصورة أفضل من قرار متسرع تندم عليه لسنوات.</p></article><aside class="fact-rail"><span class="tag">⌖ قاعدة عامة</span><div><b>القاعدة الأولى</b><span>كل التزام مؤثر يجب أن يكون مكتوبًا.</span></div><div><b>القاعدة الثانية</b><span>قارن الوحدات المتشابهة فقط في المساحة والتشطيب والتسليم.</span></div><div><b>القاعدة الثالثة</b><span>الضغط الزمني ليس سببًا لتجاوز المراجعة.</span></div></aside></div></section>${refsHtml()}</main>`;


