  "osama-bin-zaid-complex": { stage: "رياض أطفال · ابتدائي · إعدادي", system: "تعليم حكومي بالمنهج الوطني", district: "حي الكرامة · الإسكان الاجتماعي", checks: ["تحقق من نطاق القبول الجغرافي", "اسأل عن كثافة الفصول في المرحلة المطلوبة", "راجع توقيت التقديم السنوي"] },
