const obourVsNew = `<main>\${pageHero({tag:"مقارنة", eyebrow:"العبور vs العبور الجديدة", title:"ما الفرق بين العبور والعبور الجديدة؟", description:"دليل عملي يوضح الفرق بين مدينة العبور القائمة والعبور الجديدة من حيث الموقع، الخدمات، الأسعار، والمرحلة العمرانية — لمساعدتك في اختيار الأنسب قبل الشراء."})}\${atlasBody("نقطة تمييز", "الاسم متشابه لكن المدينتان مختلفتان تمامًا في العمر والخدمات وطبيعة السكن.")}<section class="paper section"><div class="wrap content-grid"><article><h2>لماذا يُخلَط بينهما؟</h2><p>التشابه في الاسم سبب رئيسي للخلط. "العبور" قد تعني المدينة القائمة غرب القناة، وقد تعني المدينة الجديدة شرقها. لكن الفرق بينهما ليس مجرد امتداد جغرافي؛ هو فرق في العمر العمراني، الكثافة، الخدمات، وطبيعة السكن. العبور القائمة مدينة عمرها عقود وتتميز بخدمات ناضجة وشوارع مكتملة، بينما العبور الجديدة مدينة مخططة من الصفر بدأ تنفيذها 2016 وتنمو على مراحل.</p><h2>جدول مقارنة سريع</h2><div class="data-table"><div><b>المعيار</b><b>العبور القائمة</b><b>العبور الجديدة</b></div><div><span>تاريخ الإنشاء</span><span>عقود (مدينة قديمة)</span><span>2016 (مدينة جديدة)</span></div><div><span>طبيعة المدينة</span><span>نمو عضوي تدريجي</span><span>تخطيط مركزي منظم</span></div><div><span>الخدمات</span><span>ناضجة ومكتملة في معظم المناطق</span><span>تنمو حسب مرحلة كل حي</span></div><div><span>المدارس</span><span>مدارس قديمة ومتوسطة النضج</span><span>مدارس حديثة + مدارس دولية</span></div><div><span>المستشفيات</span><span>مستشفيات حكومية وخاصة متعددة</span><span>مراكز صحية + مستشفيات تحت الإنشاء</span></div><div><span>المواصلات</span><span>أتوبيسات + ميكروباص + مترو العبور</span><span>LRT + محاور جديدة + أتوبيسات</span></div><div><span>الأسعار</span><span>أعلى نسبيًا بسبب النضج</span><span>متنوعة حسب مرحلة الحي</span></div><div><span>الكثافة</span><span>مرتفعة في مراكز المدينة</span><span>منخفضة نسبيًا + مساحات خضراء</span></div></div><h2>متى تختار العبور القائمة؟</h2><p>اختر العبور القائمة إذا كنت تبحث عن:</p><ul class="check-list"><li>✓ سكن فوري بخدمات جاهزة (مدارس، مستشفيات، أسواق)</li><li>✓ مواصلات متنوعة ومتكررة إلى القاهرة والقليوبية</li><li>✓ مجتمع ناضج مع خدمات يومية متاحة</li><li>✓ استثمار عقاري بعائد إيجاري مستقر</li><li>✓ سكن للعمل في مناطق شرق القاهرة أو العاشر من رمضان</li></ul><h2>متى تختار العبور الجديدة؟</h2><p>اختر العبور الجديدة إذا كنت تبحث عن:</p><ul class="check-list"><li>✓ سكن حديث بتصميم عصري ومساحات خضراء</li><li>✓ فرص شراء بسعر أقل في مراحل مبكرة</li><li>✓ مدارس دولية ولغات حديثة</li><li>✓ استثمار طويل الأجل مع نمو متوقع</li><li>✓ سكن هادئ بعيدًا عن الزحام</li><li>✓ قرب من القطار الكهربائي LRT والعاصمة الإدارية</li></ul><h2>الخلاصة</h2><p>لا يوجد "أفضل" مطلق. العبور القائمة تناسب من يريد السكن الفوري بالخدمات، والعبور الجديدة تناسب من يقبل الانتظار مقابل سعر أقل وتصميم أحدث. القرار يعتمد على هدفك الزمني وميزانيتك وطبيعة عملك.</p></article><aside class="action-card"><p>خطوتك التالية</p><a class="button" href="/districts/">استكشف أحياء العبور الجديدة ↖</a><a class="text-link" href="/old-obour/">دليل العبور القائمة ↖</a><a class="text-link" href="/prices/">قارن الأسعار ↖</a></aside></div></section>\${refsHtml()}</main>`;

const oldObour = `<main>\${pageHero({tag:"دليل العبور القديمة", eyebrow:"المدينة الأم", title:"دليل العبور القائمة: خدمات وأسعار ومواصلات", description:"دليل شامل لمدينة العبور القائمة (القديمة): الموقع، الخدمات الناضجة، المدارس، المستشفيات، الأسواق، المواصلات، وفرص السكن والاستثمار — بمصادر منشورة."})}\${atlasBody("بطاقة تعريفية", "مدينة عمرها عقود من النمو العضوي، تتميز بخدمات ناضجة وموقع استراتيجي بين القاهرة والقليوبية.")}<section class="paper section"><div class="wrap content-grid"><article><h2>نبذة عن مدينة العبور القائمة</h2><p>مدينة العبور (القائمة) هي إحدى مدن محافظة القليوبية، تقع على بعد حوالي 35 كم شمال شرق القاهرة. تأسست كمدينة صناعية وسكنية وتطورت عبر عقود لتصبح واحدة من أكبر المدن العمرانية في شرق الدلتا. تتميز بموقع استراتيجي على طريق القاهرة–الإسماعيلية الصحراوي، مما يسهل الوصول إليها من القاهرة والعاشر من رمضان والإسماعيلية.</p><h2>الموقع والوصول</h2><p>تقع العبور القائمة على الطريق الصحراوي القاهرة–الإسماعيلية، وتتصل بعدة محاور رئيسية:</p><ul class="check-list"><li>✓ طريق القاهرة–الإسماعيلية الصحراوي (الرئيسي)</li><li>✓ الطريق الدائري (اتصال بالقاهرة والجيزة)</li><li>✓ محور المشير طنطاوي (اتصال بالتجمع الخامس)</li><li>✓ مترو العبور (خط القاهرة–العبور–الإسماعيلية المخطط)</li><li>✓ أتوبيسات عامة وميكروباص إلى ميدان العباسية ورمسيس</li></ul><h2>الخدمات والمرافق</h2><p>تتميز العبور القائمة بخدمات ناضجة ومكتملة في معظم المناطق:</p><div class="data-table"><div><b>الخدمة</b><b>الوضع الحالي</b></div><div><span>مدارس حكومية</span><span>مكتملة — ابتدائي وإعدادي وثانوي</span></div><div><span>مدارس خاصة ولغات</span><span>متاحة بكثافة في المناطق الراقية</span></div><div><span>مستشفيات حكومية</span><span>مستشفى العبور العام + مستشفى النصر</span></div><div><span>مستشفيات خاصة</span><span>عدة مستشفيات ومراكز طبية متاحة</span></div><div><span>صيدليات</span><span>مكتملة — سلاسل وصيدليات مناوبة</span></div><div><span>أسواق تجارية</span><span>سوق الجمعة + أسواق تجارية كبرى</span></div><div><span>مولات</span><span>مولات متوسطة + هايبر ماركتس</span></div><div><span>بنوك</span><span>فروع لمعظم البنوك الرئيسية</span></div></div><h2>الأحياء الرئيسية</h2><p>تضم العبور القائمة عدة مناطق سكنية وتجارية وصناعية:</p><ul class="check-list"><li>✓ <strong>الحي الأول والثاني:</strong> مناطق سكنية قديمة بخدمات مكتملة</li><li>✓ <strong>حي الزهور:</strong> منطقة سكنية متوسطة الدخل</li><li>✓ <strong>حي السلام:</strong> منطقة سكنية وتجارية نشطة</li><li>✓ <strong>منطقة الاستاد:</strong> منطقة رياضية وترفيهية</li><li>✓ <strong>المنطقة الصناعية:</strong> مجمع صناعي كبير يوفر فرص عمل</li><li>✓ <strong>منطقة الجامعة:</strong> قرب جامعة العبور ومعهد الصحة</li></ul><h2>لماذا تُهمّ العبور القائمة اليوم؟</h2><p>رغم الاهتمام المتزايد بالعبور الجديدة، تظل العبور القائمة خيارًا عمليًا للعديد من الفئات:</p><p><strong>للسكن العائلي:</strong> خدمات مكتملة، مدارس قريبة، مستشفيات متاحة، وأسواق تغطي الاحتياجات اليومية.</p><p><strong>للاستثمار الإيجاري:</strong> طلب إيجاري مستقر بسبب القرب من القاهرة والمناطق الصناعية.</p><p><strong>للعمل:</strong> قرب من المنطقة الصناعية وجامعة العبور والمستشفيات.</p><p><strong>للتعليم:</strong> جامعة العبور ومعهد الصحة العالي ومدارس متنوعة.</p><h2>الفرص والتحديات</h2><p><strong>الفرص:</strong></p><ul class="check-list"><li>✓ خدمات ناضجة لا تحتاج انتظار</li><li>✓ مواصلات متنوعة ومتكررة</li><li>✓ مجتمع نشط وأسواق متاحة</li><li>✓ قرب من القاهرة والصناعية</li></ul><p><strong>التحديات:</strong></p><ul class="check-list"><li>✓ كثافة سكانية مرتفعة في بعض المناطق</li><li>✓ ازدحام مروري في أوقات الذروة</li><li>✓ قِدم بعض المرافق في الأحياء القديمة</li></ul><h2>كيف تقرر؟</h2><p>إذا كنت تبحث عن سكن فوري بخدمات جاهزة، فالعبور القائمة خيار عملي. إذا كنت تبحث عن استثمار إيجاري مستقر، فالطلب هنا مضمون نسبيًا. أما إذا كنت تفضل التصميم الحديث والمساحات الخضراء، فقد تناسبك العبور الجديدة أكثر.</p></article><aside class="action-card"><p>خطوتك التالية</p><a class="button" href="/obour-vs-obour-new/">قارن بين المدينتين ↖</a><a class="text-link" href="/transport/">مواصلات العبور الجديدة ↖</a><a class="text-link" href="/prices/">أسعار العقارات ↖</a></aside></div></section>\${refsHtml()}</main>`;

