const livingGuide = `<main>\${pageHero({tag:"دليل العيش", eyebrow:"حياة يومية في العبور", title:"دليل العيش في العبور: كل ما تحتاجه قبل الانتقال", description:"دليل شامل للحياة اليومية في العبور والعبور الجديدة: المواصلات، الخدمات، التسوق، التعليم، الصحة، والترفيه — بمصادر منشورة وقابلة للتحقق."})}\${atlasBody("خريطة الحياة اليومية", "السكن ليس جدارًا فقط؛ هو رحلة الصباح، قرب المدرسة، أقرب صيدلية، وسرعة الوصول للعمل.")}<section class="paper section"><div class="wrap content-grid"><article><h2>نظرة عامة على العيش في العبور</h2><p>مدينة العبور، سواء القائمة أو الجديدة، تقدم نموذجًا حضريًا يجمع بين القرب من القاهرة والمساحات الأوسع. العبور القائمة مدينة ناضجة بخدمات مكتملة ومجتمع نشط، بينما العبور الجديدة توفر تصميمًا عصريًا ومساحات خضراء وفرص سكنية متنوعة. الاختيار بينهما يعتمد على أولوياتك: السكن الفوري بالخدمات، أم الاستثمار في مدينة نامية.</p><h2>المواصلات والوصول اليومي</h2><p>العبور القائمة متصلة بالقاهرة عبر طريق القاهرة–الإسماعيلية الصحراوي، أتوبيسات عامة، ميكروباص، وخطوط سكة حديد. العبور الجديدة تستفيد من القطار الكهربائي LRT الذي يربطها بالعاصمة الإدارية وشرق القاهرة، إضافة إلى محور R2 والطريق الدائري الأوسطي. قبل اختيار السكن، اختبر زمن الرحلة فعليًا في وقت الذروة، لا على الخريطة.</p><div class="data-table"><div><b>وسيلة المواصلات</b><b>العبور القائمة</b><b>العبور الجديدة</b></div><div><span>القطار الكهربائي</span><span>غير متاح حاليًا</span><span>LRT (متاح/قريب التشغيل)</span></div><div><span>الأتوبيس</span><span>متاح بكثافة</span><span>متاح مع توسع الخطوط</span></div><div><span>الميكروباص</span><span>متاح لمعظم الاتجاهات</span><span>متاح للاتجاهات الرئيسية</span></div><div><span>الطريق السريع</span><span>الصحراوي القاهرة–الإسماعيلية</span><span>محور R2 + الدائري الأوسطي</span></div></div><h2>التسوق والمولات</h2><p>العبور القائمة تضم أسواقًا تقليدية مثل سوق الجمعة، إضافة إلى هايبر ماركتس ومحلات تجارية منتشرة في الأحياء. العبور الجديدة تضم مولات حديثة مثل عبور سيتي مول وجولف سيتي مول، مع توقع افتتاح مزيد من المراكز التجارية مع زيادة الكثافة السكانية. السوبر ماركتس الكبرى (كارفور، سعودي ماركت) متاحة في كلا المدينتين.</p><h2>المدارس والتعليم</h2><p>العبور القائمة تضم مدارس حكومية ناضجة ومدارس خاصة ولغات. العبور الجديدة تضم مدارس حديثة تشمل المدارس الدولية (IPS)، مدارس النيل المصرية، والمدارس المصرية اليابانية، إضافة إلى المدارس الحكومية والخاصة. التنوع التعليمي في العبور الجديدة يجذب العائلات الباحثة عن خيارات تعليمية متقدمة.</p><h2>الخدمات الصحية</h2><p>العبور القائمة تضم مستشفيات حكومية (مستشفى العبور العام، مستشفى النصر) وعدة مستشفيات ومراكز طبية خاصة. العبور الجديدة تضم مراكز صحية ومستشفيات تحت الإنشاء، مع توفر صيدليات متعددة في معظم الأحياء. للطوارئ، يمكن الوصول إلى مستشفيات العبور القائمة خلال 10–20 دقيقة من معظم أحياء العبور الجديدة.</p><h2>الأمن والنظافة</h2><p>العبور القائمة، كمدينة ناضجة، تتمتع بوجود أمني منتشر ونظافة نسبية في معظم المناطق. العبور الجديدة، كمدينة مخططة حديثًا، تتميز بتصميم يأخذ في الاعتبار الأمن من المرحلة الأولى، مع حراسة على بوابات الكمبوندات والأحياء المغلقة. النظافة في المدن الجديدة تبدأ جيدة لكنها تتطلب إدارة مستدامة مع زيادة السكان.</p><h2>الترفيه والرياضة</h2><p>العبور القائمة تضم نادي العبور الرياضي واستاد المدينة. العبور الجديدة تضم نوادي رياضية ومراكز لياقة بدنية متعددة، إضافة إلى مساحات خضراء وحدائق عامة مخططة. مع نمو المدينة، يتوقع افتتاح المزيد من المرافق الترفيهية والرياضية.</p><h2>كيف تختار بين العبور القائمة والجديدة للسكن؟</h2><p>اختر <strong>العبور القائمة</strong> إذا كنت تبحث عن: سكن فوري، خدمات مكتملة، مواصلات متنوعة، استثمار إيجاري مستقر، أو عمل في شرق القاهرة.</p><p>اختر <strong>العبور الجديدة</strong> إذا كنت تبحث عن: تصميم عصري، مساحات خضراء، مدارس دولية، أسعار أقل في مراحل مبكرة، استثمار طويل الأجل، أو قرب من القطار الكهربائي والعاصمة الإدارية.</p></article><aside class="action-card"><p>خطوتك التالية</p><a class="button" href="/districts/">استكشف الأحياء ↖</a><a class="text-link" href="/transport/">احسب زمن الرحلة ↖</a><a class="text-link" href="/schools/">دليل المدارس ↖</a><a class="text-link" href="/obour-vs-obour-new/">قارن بين المدينتين ↖</a></aside></div></section>\${refsHtml()}</main>`;

const shoppingGuide = `<main>\${pageHero({tag:"التسوق", eyebrow:"مولات وأسواق", title:"دليل التسوق في العبور: مولات، هايبر، وأسواق", description:"دليل التسوق في العبور والعبور الجديدة: المولات الكبرى، السوبر ماركتس، الأسواق التقليدية، ومحلات البقالة — بالمواقع وأوقات العمل."})}\${atlasBody("خريطة التسوق", "التسوق اليومي يحدد جودة الحياة أكثر من أي ميزة أخرى.")}<section class="paper section"><div class="wrap content-grid"><article><h2>مولات ومراكز تجارية</h2><p>العبور الجديدة تضم مولات حديثة توفر تجربة تسوق متكاملة. <strong>عبور سيتي مول</strong> و<strong>جولف سيتي مول</strong> من أبرز المراكز التجارية، ويضمان محلات تجارية متنوعة، مطاعم، كافيهات، وخدمات ترفيهية. هذه المولات تخدم سكان العبور الجديدة والمناطق المجاورة.</p><p>العبور القائمة تضم مولات متوسطة الحجم ومراكز تجارية منتشرة في الأحياء الرئيسية، مع توفر خدمات التسوق اليومي في معظم المناطق السكنية.</p><h2>هايبر ماركتس وسوبر ماركتس</h2><p>سلاسل السوبر ماركت الكبرى متاحة في كلا المدينتين. <strong>كارفور</strong> و<strong>سعودي ماركت</strong> من أبرز السلاسل المتاحة، إضافة إلى محلات بقالة محلية تغطي الاحتياجات اليومية. في الأحياء السكنية الجديدة، تتوفر محلات صغيرة تغطي الاحتياجات الأساسية مع توقع افتتاح فروع أكبر مع زيادة الكثافة.</p><h2>أسواق العبور التقليدية</h2><p><strong>سوق الجمعة</strong> في العبور القائمة من أشهر الأسواق الشعبية في المنطقة، ويقدم منتجات متنوعة بأسعار تنافسية. الأسواق المحلية في الأحياء تغطي احتياجات الخضار والفاكهة واللحوم والدواجن اليومية.</p><h2>خدمات التوصيل</h2><p>خدمات توصيل الطلبات متاحة في معظم أحياء العبور من تطبيقات مثل طلبات، جلوفو، وكريم. في المناطق الجديدة، قد تكون التغطية أقل في المراحل الأولى، لكنها تتحسن مع زيادة السكان.</p></article><aside class="action-card"><p>اكتشف المزيد</p><a class="button" href="/restaurants/">المطاعم والكافيهات ↖</a><a class="text-link" href="/directory/">كل أدلة الخدمات ↖</a></aside></div></section>\${refsHtml()}</main>`;

const diningGuide = `<main>\${pageHero({tag:"المطاعم", eyebrow:"أكل وشرب", title:"دليل الأكل في العبور: مطاعم، كافيهات، وتوصيل", description:"دليل الطعام في العبور: أفضل المطاعم، الكافيهات، خدمات التوصيل، والأماكن المناسبة للعائلات — بالأحياء والأسعار."})}\${atlasBody("خريطة الأكل", "300+ مطعم وكافيه في العبور، من الفول والطعمية للمأكولات اليابانية.")}<section class="paper section"><div class="wrap content-grid"><article><h2>مطاعم العبور المتنوعة</h2><p>يضم دليل المطاعم في العبور أكثر من 300 مطعم وكافيه، يغطي جميع الأذواق والميزانيات. من المطاعم الشعبية في حي الشباب والحي الأول، إلى سلاسل الوجبات السريعة في جولف سيتي (ماكدونالدز، KFC، بيتزا هت، بافالو برجر)، إلى المطاعم الفاخرة والكافيهات العصرية.</p><h2>المأكولات المتاحة</h2><ul class="check-list"><li>✓ <strong>مصري:</strong> كشري، فول، طعمية، مشويات، كبابجي</li><li>✓ <strong>سوري/شامي:</strong> فتة، شاورما، كبة، حمص</li><li>✓ <strong>أسماك:</strong> مطاعم متخصصة في الأسماك الطازجة</li><li>✓ <strong>وجبات سريعة:</strong> برجر، بيتزا، فراخ مقلية</li><li>✓ <strong>كافيهات:</strong> قهوة مختصة، حلويات، آيس كريم</li><li>✓ <strong>آسيوي:</strong> سوشي، صيني، ياباني</li></ul><h2>أفضل مناطق المطاعم</h2><p><strong>جولف سيتي:</strong> تجمع سلاسل الوجبات السريعة والكافيهات العصرية.</p><p><strong>حي الشباب والحي الأول:</strong> مطاعم شعبية وأسعار اقتصادية.</p><p><strong>الحي السادس والتاسع:</strong> تنوع بين المطاعم المحلية والكافيهات.</p><h2>خدمات التوصيل</h2><p>خدمات توصيل الطعام متاحة في معظم أحياء العبور. التطبيقات الرئيسية (طلبات، جلوفو) تغطي المناطق الرئيسية، مع توقع توسع التغطية في الأحياء الجديدة.</p></article><aside class="action-card"><p>استكشف المطاعم</p><a class="button" href="/restaurants/">دليل 300+ مطعم ↖</a><a class="text-link" href="/restaurants/mashawi/">مطاعم المشويات ↖</a><a class="text-link" href="/restaurants/fast-food/">وجبات سريعة ↖</a></aside></div></section>\${refsHtml()}</main>`;

const educationGuide = `<main>\${pageHero({tag:"التعليم", eyebrow:"مدارس وجامعات", title:"دليل التعليم في العبور: مدارس، حضانات، وجامعات", description:"دليل التعليم في العبور والعبور الجديدة: المدارس الحكومية، الخاصة، الدولية، اليابانية، حضانات، وجامعة العبور — بالأنظمة والمصروفات."})}\${atlasBody("خريطة التعليم", "المدرسة القريبة تغيّر جودة حياة العائلة أكثر من أي ميزة في الشقة.")}<section class="paper section"><div class="wrap content-grid"><article><h2>أنظمة التعليم في العبور</h2><p>تتنوع الخيارات التعليمية في العبور بين المدارس الحكومية التقليدية والمدارس الخاصة والدولية. العبور القائمة تضم مدارس حكومية ناضجة ومدارس خاصة، بينما العبور الجديدة تستضيف مدارس حديثة بتصميم عصري وأنظمة تعليمية متقدمة.</p><h2>المدارس الحكومية</h2><p>متاحة في العبور القائمة بكثافة، وتغطي جميع المراحل (ابتدائي، إعدادي، ثانوي). الأولوية للقبول تعتمد على محل الإقامة. في العبور الجديدة، تُفتتح مدارس حكومية جديدة مع نمو الأحياء.</p><h2>المدارس الخاصة واللغات</h2><p>مدارس خاصة متعددة في العبور القائمة تقدم مناهج وطنية مع تعزيز اللغات. مصروفاتها متوسطة إلى مرتفعة، وتتطلب التقديم المبكر.</p><h2>المدارس الدولية (IPS)</h2><p>مدارس رسمية دولية تقدم مناهج دولية بإشراف حكومي. متاحة في العبور الجديدة (الحي الثالث) والعبور القائمة (فرع روضة العبور). مصروفاتها أعلى من الحكومية لكنها أقل من المدارس الدولية الخاصة.</p><h2>مدارس النيل المصرية (NIS)</h2><p>شبكة مدارس حكومية دولية تقدم منهجًا متقدمًا. فرع العبور متاح للمراحل المتعددة. المصروفات متوسطة وآلية القبول تتم عبر الموقع الرسمي.</p><h2>المدارس المصرية اليابانية (توكاتسو)</h2><p>تقدم منهجًا وطنيًا مع أنشطة توكاتسو اليابانية (الرياضة، الفنون، الموسيقى). تقع في الحي السابع بالقرب من كارفور العبور. القبول يتم عبر بوابة المدارس المصرية اليابانية.</p><h2>الحضانات</h2><p>العبور القائمة تضم حضانات متعددة في معظم الأحياء. العبور الجديدة تضم حضانات حديثة مع توقع افتتاح المزيد مع زيادة عدد العائلات.</p><h2>جامعة العبور</h2><p>تقع في العبور القائمة وتقدم تخصصات متنوعة في العلوم الإدارية والتربية والتمريض وغيرها. توفر الجامعة خيارًا تعليميًا جامعيًا قريبًا لسكان العبور.</p></article><aside class="action-card"><p>اكتشف المدارس</p><a class="button" href="/schools/">دليل المدارس ↖</a><a class="text-link" href="/nurseries/">الحضانات ↖</a><a class="text-link" href="/directory/">كل الخدمات ↖</a></aside></div></section>\${refsHtml()}</main>`;

const healthGuide = `<main>\${pageHero({tag:"الصحة", eyebrow:"مستشفيات وصيدليات", title:"دليل الصحة في العبور: مستشفيات، عيادات، وطوارئ", description:"دليل الخدمات الصحية في العبور والعبور الجديدة: المستشفيات، العيادات، الصيدليات، وأرقام الطوارئ — بالمواقع وأوقات العمل."})}\${atlasBody("خريطة الصحة", "أقرب صيدلية ومستشفى معلومة تسبق السعر في ترتيب أولويات السكن.")}<section class="paper section"><div class="wrap content-grid"><article><h2>المستشفيات في العبور القائمة</h2><p>تضم العبور القائمة عدة مستشفيات حكومية وخاصة تغطي احتياجات السكان:</p><ul class="check-list"><li>✓ <strong>مستشفى العبور العام:</strong> مستشفى حكومي يقدم خدمات متنوعة</li><li>✓ <strong>مستشفى النصر:</strong> مستشفى حكومي آخر في المدينة</li><li>✓ <strong>مستشفيات خاصة:</strong> عدة مراكز طبية ومستشفيات خاصة متاحة</li></ul><h2>المرافق الصحية في العبور الجديدة</h2><p>العبور الجديدة تضم مراكز صحية تقدم الخدمات الأساسية، مع مستشفيات تحت الإنشاء. للحالات الطارئة، يمكن الوصول إلى مستشفيات العبور القائمة خلال 10–20 دقيقة من معظم الأحياء.</p><h2>الصيدليات</h2><p>يوجد في العبور أكثر من 42 صيدلية، منها سلاسل كبرى (العزبي، سيف، 19011) وصيدليات مستقلة. بعض الصيدليات تقدم خدمة 24 ساعة. دليل الصيدليات متاح مع عناوين وأرقام التليفون.</p><h2>العيادات المتخصصة</h2><p>عيادات متخصصة متاحة في العبور القائمة تغطي معظم التخصصات الطبية. العبور الجديدة تشهد افتتاح عيادات جديدة مع نمو السكان.</p><h2>أرقام الطوارئ</h2><div class="data-table"><div><b>الخدمة</b><b>الرقم</b></div><div><span>الإسعاف</span><span>123</span></div><div><span>الشرطة</span><span>122</span></div><div><span>المطافئ</span><span>180</span></div><div><span>الكهرباء</span><span>121</span></div><div><span>المياه</span><span>125</span></div><div><span>الغاز</span><span>129</span></div></div></article><aside class="action-card"><p>اكتشف المزيد</p><a class="button" href="/pharmacies/">دليل 42 صيدلية ↖</a><a class="text-link" href="/health/">الصحة والمستشفيات ↖</a><a class="text-link" href="/emergency/">أرقام الطوارئ ↖</a></aside></div></section>\${refsHtml()}</main>`;

const priceReport = `<main>\${pageHero({tag:"تقرير أسعاري", eyebrow:"ربع سنوي · قابل للتحميل", title:"تقرير أسعار العقارات في العبور الجديدة — الربع الثالث 2026", description:"دراسة شاملة لأسعار العقارات في العبور الجديدة: متوسط المتر، نطاقات الأسعار، مقارنة بالمدن المجاورة، وتحليل الاتجاهات — بيانات منشورة قابلة للتحقق."})}\${atlasBody("بطاقة إحصائية", "تقرير ربع سنوي يجمع بيانات الأسعار من مصادر متعددة ويقدمها في صورة قابلة للمقارنة والتحليل.")}<section class="paper section"><div class="wrap content-grid"><article><h2>ملخص التقرير</h2><p>يغطي هذا التقرير أسعار العقارات في مدينة العبور الجديدة للربع الثالث من عام 2026. البيانات مأخوذة من إعلانات منشورة، بيانات مطورين، ومؤشرات سوقية معلنة. الهدف ليس توفير سعر دقيق لكل وحدة، بل تقديم نطاق استرشادي يساعد المشتري على بناء مقارنة أولية قبل المعاينة.</p><div class="data-table"><div><b>المؤشر</b><b>القيمة</b></div><div><span>متوسط سعر المتر (شقة)</span><span>7,500–12,000 ج.م</span></div><div><span>نطاق الشقق الصغيرة (70–90 م²)</span><span>550,000–950,000 ج.م</span></div><div><span>نطاق الشقق المتوسطة (100–130 م²)</span><span>850,000–1,400,000 ج.م</span></div><div><span>نطاق الشقق الكبيرة (140–180 م²)</span><span>1,200,000–2,000,000 ج.م</span></div><div><span>فيلات (200–350 م²)</span><span>2,500,000–5,000,000 ج.م</span></div><div><span>تجاري (محلات)</span><span>12,000–25,000 ج.م/م²</span></div></div><h2>مقارنة مع مدن مجاورة</h2><div class="data-table"><div><b>المدينة</b><b>متوسط المتر (شقة)</b><b>ملاحظة</b></div><div><span>العبور الجديدة</span><span>7,500–12,000 ج.م</span><span>مدينة نامية، فرص شراء مبكر</span></div><div><span>التجمع الخامس</span><span>15,000–28,000 ج.م</span><span>سوق ناضج، سيولة أعلى</span></div><div><span>الشروق</span><span>9,000–14,000 ج.م</span><span>نمو متوسط، كثافة أقل</span></div><div><span>العاصمة الإدارية</span><span>18,000–35,000 ج.م</span><span>حديثة، مساحات داخلية كبيرة</span></div><div><span>العبور القائمة</span><span>10,000–16,000 ج.م</span><span>خدمات ناضجة، سكن فوري</span></div></div><h2>عوامل تؤثر على السعر</h2><ul class="check-list"><li>✓ <strong>المرحلة:</strong> الأحياء المكتملة أغلى من الأحياء قيد التنفيذ</li><li>✓ <strong>الموقع:</strong> القرب من محور رئيسي أو محطة LRT يرفع السعر</li><li>✓ <strong>المطور:</strong> سابقة الأعمال والسمعة تؤثر على قيمة إعادة البيع</li><li>✓ <strong>الخدمات:</strong> توفر المدارس والمستشفيات القريبة عامل جذب</li><li>✓ <strong>التشطيب:</strong> الوحدات المتشطبة أغلى بنسبة 20–40%</li></ul><h2>الاتجاهات الملاحظة</h2><p>شهد الربع الثالث من 2026 استقرارًا نسبيًا في الأسعار مع زيادة طفيفة في الأحياء القريبة من محطات LRT. الأحياء الجديدة (الحي 24، 25) تقدم فرص شراء بأسعار أقل مقابل انتظار اكتمال الخدمات. الطلب الإيجاري مستقر في الأحياء المكتملة، مما يدعم الاستثمار الإيجاري.</p><h2>إخلاء المسؤولية</h2><p>هذا التقرير إرشادي ولا يُعتبر توصية بالشراء أو البيع. الأسعار الفعلية تختلف حسب الموقع الدقيق، حالة الوحدة، والتفاوض. يُنصح بزيارة الموقع والتحقق من المستندات قبل أي التزام.</p></article><aside class="action-card"><p>استخدم التقرير</p><a class="button" href="/prices/">قراءة الأسعار التفصيلية ↖</a><a class="text-link" href="/compare/">مقارنة مع مدن أخرى ↖</a><a class="text-link" href="/investment/">دليل الاستثمار ↖</a><a class="text-link" href="/developers/">تقييم المطورين ↖</a></aside></div></section>\${refsHtml()}</main>`;

