// صفحة لكل دليل بيانات (عدا schools-all فهي قسم داخل صفحة المدارس)
for (const d of directories) {
  if (d.slug === "schools-all") continue;
  pages.push([
    d.slug,
    d.title,
    `${d.title} في مدينة العبور: ${d.items.length} مدخلًا بالاسم والعنوان ورقم الهاتف ومصدر قابل للمراجعة. ${d.lead}`,
    `${d.title} العبور, ${d.title} مدينة العبور, دليل ${d.title} العبور, ارقام ${d.title} العبور`,
    { "@context": "https://schema.org", "@type": "ItemList", name: `${d.title} في مدينة العبور`,
      numberOfItems: d.items.length,
      itemListElement: d.items.slice(0, 60).map((it, i) => ({
        "@type": "ListItem", position: i + 1,
        item: localBusinessSchema(it, i + 1, d.slug, d.slug),
      })) },
    directoryPage(d),
  ]);
}


// صفحات الهبوط الفرعية
for (const L of landings) {
  const d = dirBySlug[L.parent];
  const items = d.items.filter((it) => it.c === L.sub);
  pages.push([
    `${L.parent}/${L.slug}`,
    L.title,
    L.desc,
    L.kw,
    { "@context": "https://schema.org", "@type": "ItemList", name: L.title, numberOfItems: items.length,
      itemListElement: items.slice(0, 40).map((it, i) => ({ "@type": "ListItem", position: i + 1,
        item: localBusinessSchema(it, i + 1, `${L.parent}/${L.slug}`, L.parent) })) },
    landingPage(L),
  ]);
}

for (const [slug, title, description, keywords, schema, body] of pages) write(slug, layout({ slug, title, description, keywords, schema, body }));

// individual school pages
for (const sc of realSchools) {
  const n = schoolNotes[sc.slug] || {};
  write(`schools/${sc.slug}`, layout({
    slug: `schools/${sc.slug}`,
    title: sc.name,
    description: `${sc.name} — ${sc.type} في ${sc.area}. بيانات موثقة وأسئلة عملية قبل التقديم، من دليل مدينة العبور الجديدة.`,
    keywords: `${sc.name}, مدارس العبور الجديدة, ${n.district||sc.area}, ${sc.type}`,
    schema: { "@context":"https://schema.org", "@type":"School", name: sc.name,
      description: `${sc.type} — ${sc.area}`,
      address: { "@type":"PostalAddress", addressLocality: "مدينة العبور الجديدة", addressRegion:"القليوبية", addressCountry:"EG", streetAddress: sc.area },
      areaServed: sc.group, url: `${site}/schools/${sc.slug}/`,
      sameAs: [sc.source] },
    body: schoolPage(sc),
  }));
}
write("404", layout({ slug:"404", title:"الصفحة غير موجودة", description:"الصفحة المطلوبة غير موجودة في دليل مدينة العبور الجديدة.", keywords:"دليل مدينة العبور الجديدة", schema:{"@context":"https://schema.org","@type":"WebPage",name:"404"}, body:`<main class="not-found section"><div class="wrap"><p class="eyebrow">خطأ 404</p><h1>لم نجد هذا المسار</h1><p>ربما تغير الرابط، أو يمكنك الرجوع إلى خريطة الدليل والبدء من جديد.</p><a class="button" href="/">العودة للرئيسية</a></div></main>` }));
fs.mkdirSync(publicDir, { recursive: true });
fs.writeFileSync(path.join(publicDir, "robots.txt"), `User-agent: *\nAllow: /\n\nSitemap: ${site}/sitemap.xml\n`);
fs.writeFileSync(path.join(publicDir, "sitemap.xml"), `<?xml version="1.0" encoding="UTF-8"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">\n${[...pages.map(([slug])=>slug).filter((slug)=>slug !== "search"), ...realSchools.map(sc=>`schools/${sc.slug}`), ...landings.map(L=>`${L.parent}/${L.slug}`)].map((slug)=>{ const isHome = slug === ""; const isPrices = slug === "prices"; const isDirectory = directories.some(d=>d.slug===slug); const isLanding = landings.some(L=>`${L.parent}/${L.slug}`===slug); const changefreq = isHome || isPrices ? "weekly" : isDirectory || isLanding ? "weekly" : "monthly"; const priority = isHome ? "1.0" : isPrices ? "0.9" : slug === "developers" ? "0.9" : isDirectory || isLanding ? "0.8" : slug.startsWith("schools/") ? "0.6" : "0.7"; return `  <url><loc>${slug ? `${site}/${slug}/` : `${site}/`}</loc><changefreq>${changefreq}</changefreq><priority>${priority}</priority></url>`; }).join("\n")}\n</urlset>\n`);
// نسخة 404 في جذر الإخراج: Cloudflare Pages يقدّمها بحالة 404 لأي مسار غير موجود
fs.copyFileSync(pathFor("404"), path.join(publicDir, "404.html"));

// فهرس البحث: كل الصفحات + كل مداخل الأدلة، يُقرأ في المتصفح على /search/
const searchIndex = [
  ...pages.filter(([slug]) => slug !== "search").map(([slug, title, description]) => ({
    n: title, d: description, u: slug ? `/${slug}/` : "/", k: "صفحة",
  })),
  ...realSchools.map((x) => ({ n: x.name, a: x.area, t: x.type, u: `/schools/${x.slug}/`, k: "مدرسة" })),
  ...landings.map((L) => ({ n: L.title, d: L.desc, u: `/${L.parent}/${L.slug}/`, k: "صفحة" })),
  ...directories.filter((d) => d.slug !== "schools-all").flatMap((d) =>
    d.items.map((it) => ({ n: it.n, a: it.a, t: it.c, u: `/${d.slug}/`, k: d.one }))),
  ...dirBySlug["schools-all"].items.map((it) => ({ n: it.n, a: it.a, t: it.c, u: "/schools/", k: "مدرسة" })),
];
fs.writeFileSync(path.join(publicDir, "search-index.json"), JSON.stringify(searchIndex));

console.log(`Rendered ${pages.length} main pages + ${realSchools.length} school pages + a 404 page.`);
